import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    if k > n * n:
        print(-1)
        return

    matrix = [[0] * n for _ in range(n)]

    # Place ones on the main diagonal first
    for i in range(min(k, n)):
        matrix[i][i] = 1
        k -= 1

    # Place remaining ones symmetrically above the diagonal
    for i in range(n):
        for j in range(i + 1, n):
            if k > 0:
                matrix[i][j] = 1
                matrix[j][i] = 1
                k -= 2

    if k != 0:
        print(-1)
        return

    for row in matrix:
        print(" ".join(map(str, row)))

if __name__ == "__main__":
    main()
